import * as T from './vendor/three.module.js';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
// All textures and models are generated locally. No external model downloads.
export function natureKit(scene,renderer,random){
 const r=random;const moving=[],beeTemplates=new Map();
 function mergeStatic(parent){const groups=new Map();for(const o of [...parent.children]){if(!o.isMesh||o.isInstancedMesh)continue;const list=groups.get(o.material)||[];list.push(o);groups.set(o.material,list)}for(const [m,list] of groups){if(list.length<2)continue;const gs=list.map(o=>{o.updateMatrix();return o.geometry.clone().applyMatrix4(o.matrix)});const geometry=mergeGeometries(gs);if(geometry){list.forEach(o=>parent.remove(o));const combined=new T.Mesh(geometry,m);combined.castShadow=true;combined.receiveShadow=true;parent.add(combined)}gs.forEach(o=>o.dispose())}}
 function texture(kind){const c=document.createElement('canvas');c.width=c.height=256;const a=c.getContext('2d');a.fillStyle=kind==='bark'?'#766449':'#869064';a.fillRect(0,0,256,256);for(let i=0;i<5000;i++){const v=r();a.fillStyle=kind==='bark'?`rgba(${v>.5?'33,27,18':'187,164,115'},${.08+r()*.3})`:`rgba(${v>.5?'204,185,125':'47,68,34'},${.08+r()*.2})`;const x=r()*256,y=r()*256;a.fillRect(x,y,kind==='bark'?1+r()*3:1+r()*4,kind==='bark'?8+r()*65:1+r()*5)}const tex=new T.CanvasTexture(c);tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.colorSpace=T.SRGBColorSpace;tex.anisotropy=Math.min(4,renderer.capabilities.getMaxAnisotropy());return tex}
 const bark=texture('bark'),ground=texture('ground');ground.repeat.set(65,65);
 const barkMat=new T.MeshStandardMaterial({map:bark,roughness:.98});
 const shell=new T.MeshStandardMaterial({color:'#4c3520',roughness:.48});
 const thoraxMat=new T.MeshStandardMaterial({color:'#77603c',roughness:.93});
 const eyeMat=new T.MeshStandardMaterial({color:'#151c19',roughness:.23});
 const legMat=new T.MeshStandardMaterial({color:'#4a3825',roughness:.67});
 const pollenMat=new T.MeshStandardMaterial({color:'#d5a335',roughness:1});
 const wingMat=new T.MeshStandardMaterial({color:'#d4ddd2',transparent:true,opacity:.35,roughness:.27,side:T.DoubleSide,depthWrite:false});
 const veinMat=new T.LineBasicMaterial({color:'#756e52',transparent:true,opacity:.42});
 function obj(g,m,p,parent){const o=new T.Mesh(g,m);o.position.set(...p);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
 function ell(p,s,m,parent){const o=obj(new T.SphereGeometry(1,24,16),m,p,parent);o.scale.set(...s);return o}
 function segment(a,b,r1,r2,material,parent){const va=new T.Vector3(...a),vb=new T.Vector3(...b),d=vb.clone().sub(va);const o=obj(new T.CylinderGeometry(r2,r1,d.length(),9),material,va.add(vb).multiplyScalar(.5).toArray(),parent);o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o}
 function contact(x,z,sx,sz){const c=document.createElement('canvas');c.width=c.height=64;const a=c.getContext('2d'),g=a.createRadialGradient(32,32,1,32,32,32);g.addColorStop(0,'rgba(30,32,15,.32)');g.addColorStop(1,'rgba(30,32,15,0)');a.fillStyle=g;a.fillRect(0,0,64,64);const m=new T.MeshBasicMaterial({map:new T.CanvasTexture(c),transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2});const o=obj(new T.PlaneGeometry(sx,sz),m,[x,.035,z],scene);o.rotation.x=-Math.PI/2;o.castShadow=false;}
 function bee(x,y,z,scale=1){const detail=scale>.4;if(beeTemplates.has(detail)){const g=beeTemplates.get(detail).clone(true);g.position.set(x,y,z);g.scale.setScalar(scale);scene.add(g);g.traverse(o=>{if(o.userData.wingSide)moving.push({root:o,side:o.userData.wingSide,bee:g})});return g;}const g=new T.Group();g.position.set(x,y,z);g.scale.setScalar(scale);scene.add(g);
 ell([0,.02,.49],[.22,.25,.22],shell,g);ell([0,0,.04],[.275,.27,.32],thoraxMat,g);
 const pos=[],col=[],idx=[],norm=[],rings=detail?42:18,sides=detail?32:16;
 for(let i=0;i<=rings;i++){const u=i/rings,zz=-.18-u*1.02;const radius=Math.sin(Math.PI*Math.pow(u,.74))*.315+.018;const c=new T.Color((Math.floor(u*6)%2===0)?'#b58b40':'#40321e');for(let j=0;j<=sides;j++){const a=j/sides*Math.PI*2;pos.push(Math.cos(a)*radius,Math.sin(a)*radius*.86,zz);const shade=.9+.1*Math.sin(a);col.push(c.r*shade,c.g*shade,c.b*shade);norm.push(Math.cos(a),Math.sin(a),0);if(i<rings&&j<sides){const n=i*(sides+1)+j;idx.push(n,n+sides+1,n+1,n+1,n+sides+1,n+sides+2)}}}
 const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(pos,3));geo.setAttribute('color',new T.Float32BufferAttribute(col,3));geo.setIndex(idx);geo.computeVertexNormals();obj(geo,new T.MeshStandardMaterial({vertexColors:true,roughness:.57}),[0,0,0],g);
 for(const side of [-1,1]){ell([side*.16,.07,.59],[.105,.16,.065],eyeMat,g);segment([side*.09,.18,.6],[side*.18,.37,.68],.013,.009,legMat,g);segment([side*.18,.37,.68],[side*.3,.4,.82],.009,.006,legMat,g);
 for(let k=0;k<3;k++){const zz=.22-k*.18,a=[side*.18,-.12,zz],b=[side*.4,-.27,zz+(k===0?.12:-.12)],c=[side*.51,-.48,zz+(k===0?.27:-.32)],d=[side*.62,-.49,zz+(k===0?.34:-.43)];segment(a,b,.032,.023,legMat,g);segment(b,c,k===2?.045:.025,.017,legMat,g);segment(c,d,.016,.009,legMat,g);if(k===2)ell([side*.47,-.36,zz-.23],[.08,.115,.055],pollenMat,g)}
 for(let k=0;k<2;k++){const root=new T.Group();root.userData.wingSide=side;root.position.set(side*.15,.14,.09-k*.15);root.rotation.y=side*(k===0?-.32:.38);g.add(root);const length=k===0?1.12:.73,width=k===0?.3:.22;const shape=new T.Shape();shape.moveTo(0,0);shape.bezierCurveTo(length*.4,width*.9,length*.96,width*.85,length,width*.15);shape.bezierCurveTo(length*.97,-width*.65,length*.32,-width*.65,0,0);const wg=new T.ShapeGeometry(shape,18);const w=obj(wg,wingMat,[0,0,0],root);w.rotation.x=-Math.PI/2;w.scale.x=side;w.castShadow=false;const lines=[];for(let j=0;j<4;j++){const end=length*(.4+j*.16);lines.push(0,0,0,side*end,.003,(j-1.5)*width*.23)}const v=new T.BufferGeometry();v.setAttribute('position',new T.Float32BufferAttribute(lines,3));root.add(new T.LineSegments(v,veinMat));moving.push({root,side,base:side*(k===0?-.32:.38),bee:g});}}
 // Sparse short hairs retain a readable silhouette on the enlarged specimens.
 if(scale>.4){const hp=[];for(let i=0;i<280;i++){const a=r()*Math.PI*2,b=Math.acos(r()*2-1),xx=Math.sin(b)*Math.cos(a),yy=Math.cos(b),zz=Math.sin(b)*Math.sin(a);hp.push(xx*.279,yy*.274,zz*.325+.04,xx*.315,yy*.31,zz*.36+.04)}const hgeo=new T.BufferGeometry();hgeo.setAttribute('position',new T.Float32BufferAttribute(hp,3));g.add(new T.LineSegments(hgeo,new T.LineBasicMaterial({color:'#baa273',transparent:true,opacity:.63})));}
 mergeStatic(g);if(!detail)g.traverse(o=>{if(o.isMesh)o.castShadow=false});beeTemplates.set(detail,g);return g;
 }
 const leafShape=new T.Shape();leafShape.moveTo(0,-.34);leafShape.quadraticCurveTo(.2,-.03,0,.35);leafShape.quadraticCurveTo(-.2,-.03,0,-.34);const leafGeo=new T.ShapeGeometry(leafShape,3);const lp=leafGeo.attributes.position;for(let i=0;i<lp.count;i++)lp.setZ(i,Math.abs(lp.getX(i))*.5);leafGeo.computeVertexNormals();const leafMat=new T.MeshStandardMaterial({color:'#ffffff',roughness:.84,side:T.DoubleSide});
 function tree(x,z,height){const group=new T.Group();group.position.set(x,0,z);scene.add(group);let trunk=[0,0,0];const bend=(r()-.5)*.7;const ends=[];for(let k=0;k<4;k++){const end=[bend*(k+1)/4,height*(k+1)/5,Math.sin(k)*.14];segment(trunk,end,.26-k*.045,.22-k*.045,barkMat,group);trunk=end}
 for(let k=0;k<9;k++){const a=k*2.399+ r()*.4,sy=height*(.42+r()*.37),radius=1.1+r()*1.5;const root=[bend*sy/height,sy,0],mid=[Math.cos(a)*radius*.55,sy+.55,Math.sin(a)*radius*.55],tip=[Math.cos(a)*radius,sy+.9+r()*.5,Math.sin(a)*radius];segment(root,mid,.095,.05,barkMat,group);segment(mid,tip,.05,.012,barkMat,group);ends.push(tip)}ends.push([bend,height,0]);
 const perTip=Math.abs(x)>25?42:75;const leaves=new T.InstancedMesh(leafGeo,leafMat,ends.length*perTip),dummy=new T.Object3D();let n=0;for(const tip of ends)for(let i=0;i<perTip;i++){const a=r()*Math.PI*2,rr=Math.sqrt(r())*1.25,dy=(r()-.5)*1.6;dummy.position.set(tip[0]+Math.cos(a)*rr,tip[1]+dy,tip[2]+Math.sin(a)*rr);dummy.rotation.set(r()*2.7,r()*6.28,r()*6.28);dummy.scale.setScalar(.7+r()*.8);dummy.updateMatrix();leaves.setMatrixAt(n,dummy.matrix);const c=new T.Color().setHSL(.23+r()*.055,.25+r()*.19,.19+r()*.19);leaves.setColorAt(n++,c)}leaves.castShadow=true;leaves.receiveShadow=true;group.add(leaves);mergeStatic(group);contact(x,z,4,3.5);return group;
 }
 function tick(t){for(const w of moving){const flying=w.bee.scale.x<.4;w.root.rotation.z=flying?w.side*Math.sin(t*55)*.42:w.side*(.06+Math.sin(t*.8)*.035)}}
 return {bee,tree,contact,ground,barkMat,tick};
}
